mapper.select:
SELECT CM.CUSTOMER_HS_CODE  AS customerHsCode
      ,FAHC.FTA_AGM_HS_CODE AS ftaAgmHsCode
      ,FHC.FTA_HS_CODE      AS ftaHsCode
      ,HIS.HS_CODE          AS historyHsCode
      ,IM.HS_CODE           AS itemHsCode
FROM   ITEM_MST IM
LEFT   OUTER JOIN CUSTOMER_MODEL CM
ON     CM.COMPANY_CODE = IM.COMPANY_CODE
AND    CM.ITEM_CODE = IM.ITEM_CODE
AND    CM.DIVISION_CODE = #{divisionCode}
AND    CM.CUSTOMER_CODE = #{customerCode}
LEFT   OUTER JOIN FTA_AGM_HS_CODE FAHC
ON     FAHC.COMPANY_CODE = IM.COMPANY_CODE
AND    FAHC.ITEM_CODE = IM.ITEM_CODE
AND    FAHC.FTA_CODE = #{ftaCode}
LEFT   OUTER JOIN FTA_HS_CODE FHC
ON     FHC.COMPANY_CODE = IM.COMPANY_CODE
AND    IM.ITEM_CODE = FHC.ITEM_CODE
AND    FHC.NATION_CODE = #{nationCode}
LEFT   OUTER JOIN HISTORY_ITEM_HS_CODE HIS
ON     HIS.ITEM_CODE = #{itemCode}
AND    HIS.COMPANY_CODE = #{companyCode}
AND    #{resolvedBaseDate} BETWEEN HIS.FROM_DATE AND COALESCE(HIS.TO_DATE, '99991231')
WHERE  IM.ITEM_CODE = #{itemCode}
AND    IM.COMPANY_CODE = #{companyCode}
